// A timeout bounds the wait AND propagates cancellation downstream.
func fetchUser(ctx context.Context, c *http.Client, id string) ([]byte, error) {
	// Derive a per-call budget from the caller's context.
	ctx, cancel := context.WithTimeout(ctx, 200*time.Millisecond)
	defer cancel() // always release the timer

	req, _ := http.NewRequestWithContext(ctx, "GET", "http://svc/users/"+id, nil)
	resp, err := c.Do(req) // cancelled if ctx deadline fires
	if err != nil {
		return nil, err // e.g. context.DeadlineExceeded
	}
	defer resp.Body.Close()
	return io.ReadAll(resp.Body)
}

// Exponential backoff with full jitter, capped, and context-aware.
func retry(ctx context.Context, attempts int, op func() error) error {
	var err error
	for i := 0; i < attempts; i++ {
		if err = op(); err == nil {
			return nil // success
		}
		backoff := time.Duration(1<<i) * 100 * time.Millisecond
		if backoff > 2*time.Second {
			backoff = 2 * time.Second // cap the wait
		}
		jittered := time.Duration(rand.Int63n(int64(backoff))) // full jitter
		select {
		case <-time.After(jittered):
		case <-ctx.Done():
			return ctx.Err() // respect the overall deadline
		}
	}
	return err
}

// Classify errors and require idempotency before retrying.
func safeToRetry(idempotent bool, statusCode int, err error) bool {
	if !idempotent {
		return false // never retry a non-idempotent write
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return true // transient timeout
	}
	switch statusCode {
	case 408, 429, 500, 502, 503, 504:
		return true // transient / server-side
	default:
		return false // 400/401/404 are deterministic: retrying won't help
	}
}

// A minimal breaker: fail fast while open, probe when half-open.
type Breaker struct {
	mu        sync.Mutex
	failures  int
	threshold int
	openUntil time.Time
}

func (b *Breaker) Call(op func() error) error {
	b.mu.Lock()
	if time.Now().Before(b.openUntil) { // OPEN: fail fast
		b.mu.Unlock()
		return errors.New("circuit open")
	}
	b.mu.Unlock()

	err := op() // CLOSED or HALF-OPEN: attempt the call
	b.mu.Lock()
	defer b.mu.Unlock()
	if err != nil {
		b.failures++
		if b.failures >= b.threshold {
			b.openUntil = time.Now().Add(5 * time.Second) // trip open
		}
		return err
	}
	b.failures = 0 // success closes the circuit
	return nil
}

// A semaphore bulkhead caps concurrency for one dependency.
type Bulkhead struct{ sem chan struct{} }

func NewBulkhead(limit int) *Bulkhead {
	return &Bulkhead{sem: make(chan struct{}, limit)} // capacity = max in-flight
}

func (b *Bulkhead) Do(ctx context.Context, op func() error) error {
	select {
	case b.sem <- struct{}{}: // acquire a slot
		defer func() { <-b.sem }() // release it
		return op()
	case <-ctx.Done(): // don't wait forever for a slot
		return ctx.Err()
	default:
		return errors.New("bulkhead full: rejecting to protect other pools")
	}
}

// Shed load past capacity; a bounded queue applies backpressure.
type Limiter struct{ slots chan struct{} }

func NewLimiter(capacity int) *Limiter {
	return &Limiter{slots: make(chan struct{}, capacity)}
}

// Middleware: reject immediately when at capacity.
func (l *Limiter) Handle(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		select {
		case l.slots <- struct{}{}: // admit
			defer func() { <-l.slots }()
			next.ServeHTTP(w, r)
		default: // full -> shed instead of queueing forever
			w.Header().Set("Retry-After", "1")
			http.Error(w, "overloaded", http.StatusTooManyRequests)
		}
	})
}

