package main

import (
	"context"
	"errors"
	"fmt"
	"math/rand"
	"sync"
	"time"
)

// Breaker: closed/open/half-open state over a failure counter.
type Breaker struct {
	mu        sync.Mutex
	failures  int
	threshold int
	openUntil time.Time
}

var ErrOpen = errors.New("circuit open")

func (b *Breaker) Call(op func() error) error {
	b.mu.Lock()
	if time.Now().Before(b.openUntil) { // OPEN: fail fast, no call
		b.mu.Unlock()
		return ErrOpen
	}
	b.mu.Unlock()

	err := op()
	b.mu.Lock()
	defer b.mu.Unlock()
	if err != nil {
		b.failures++
		if b.failures >= b.threshold {
			b.openUntil = time.Now().Add(2 * time.Second) // trip
		}
		return err
	}
	b.failures = 0 // success closes
	return nil
}

// resilientCall = retry( breaker( timeout( op ) ) ).
func resilientCall(ctx context.Context, b *Breaker, op func(context.Context) error) error {
	var err error
	for attempt := 0; attempt < 3; attempt++ {
		err = b.Call(func() error {
			cctx, cancel := context.WithTimeout(ctx, 150*time.Millisecond)
			defer cancel()
			return op(cctx) // per-attempt timeout
		})
		if err == nil || errors.Is(err, ErrOpen) {
			return err // success, or fail fast: don't keep retrying a dead dep
		}
		backoff := time.Duration(1<<attempt) * 50 * time.Millisecond
		select {
		case <-time.After(time.Duration(rand.Int63n(int64(backoff)))): // jitter
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	return err
}

func main() {
	b := &Breaker{threshold: 2}
	err := resilientCall(context.Background(), b, func(ctx context.Context) error {
		return errors.New("boom") // always fails to demonstrate tripping
	})
	fmt.Println("result:", err) // trips open, then returns fast
}

