package main

import (
	"context"
	"errors"
	"math/rand"
	"time"
)

var errPermanent = errors.New("permanent")

// retryable reports whether an error is transient AND safe to retry.
func retryable(err error) bool {
	if errors.Is(err, errPermanent) { // e.g. 400/404/auth -> never retry
		return false
	}
	return true // timeouts, 503, connection resets
}

// callWithRetry: exponential backoff + full jitter, capped, ctx-aware,
// and gated on whether the op is idempotent and the error is transient.
func callWithRetry(ctx context.Context, idempotent bool, op func() error) error {
	var err error
	for i := 0; i < 5; i++ {
		if err = op(); err == nil {
			return nil
		}
		if !idempotent || !retryable(err) {
			return err // unsafe or deterministic: give up immediately
		}
		backoff := time.Duration(1<<i) * 100 * time.Millisecond
		if backoff > 3*time.Second {
			backoff = 3 * time.Second // cap
		}
		select {
		case <-time.After(time.Duration(rand.Int63n(int64(backoff)))): // full jitter
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	return err
}

