type Bulkhead struct{ sem chan struct{} }

func NewBulkhead(limit int) *Bulkhead {
	return &Bulkhead{sem: make(chan struct{}, limit)} // max concurrent = limit
}

var ErrFull = errors.New("bulkhead full")

// Do runs op only if a slot is free, isolating this dependency's concurrency.
func (b *Bulkhead) Do(ctx context.Context, op func()) error {
	select {
	case b.sem <- struct{}{}: // acquire
		defer func() { <-b.sem }() // release
		op()
		return nil
	case <-ctx.Done():
		return ctx.Err()
	default:
		return ErrFull // reject rather than pile on
	}
}

func main() {
	bh := NewBulkhead(2) // only 2 in-flight at once
	var wg sync.WaitGroup
	var mu sync.Mutex
	rejected := 0
	for i := 0; i < 5; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			err := bh.Do(context.Background(), func() {
				time.Sleep(50 * time.Millisecond) // slow dependency
			})
			if errors.Is(err, ErrFull) {
				mu.Lock()
				rejected++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	fmt.Printf("rejected %d of 5 (pool contained the surge)\n", rejected)
}

