package solution

import (
	"errors"
	"sync"
	"time"
)

var ErrOpen = errors.New("circuit open")

type Breaker struct {
	Threshold   int
	CooldownFor time.Duration

	mu        sync.Mutex
	failures  int
	openUntil time.Time
}

// Call runs op unless the breaker is currently open (fail fast).
func (b *Breaker) Call(op func() error) error {
	b.mu.Lock()
	if time.Now().Before(b.openUntil) { // OPEN: reject without calling op
		b.mu.Unlock()
		return ErrOpen
	}
	b.mu.Unlock()

	// CLOSED or HALF-OPEN (cooldown elapsed): attempt the call.
	err := op()

	b.mu.Lock()
	defer b.mu.Unlock()
	if err != nil {
		b.failures++
		if b.failures >= b.Threshold { // trip open
			b.openUntil = time.Now().Add(b.CooldownFor)
		}
		return err
	}
	b.failures = 0 // success closes the circuit
	return nil
}

