package solution

import (
	"errors"
	"testing"
	"time"
)

func TestBreakerTripsAndRecovers(t *testing.T) {
	b := &Breaker{Threshold: 2, CooldownFor: 50 * time.Millisecond}
	fail := func() error { return errors.New("boom") }
	ok := func() error { return nil }

	// Two failures should trip the breaker open.
	if err := b.Call(fail); err == nil {
		t.Fatal("want error on attempt 1")
	}
	if err := b.Call(fail); err == nil {
		t.Fatal("want error on attempt 2")
	}
	// Now OPEN: should fail fast with ErrOpen, without calling op.
	called := false
	_ = b.Call(func() error { called = true; return nil })
	if called {
		t.Fatal("op should NOT run while open")
	}

	// Wait out the cooldown -> half-open -> success closes it.
	time.Sleep(60 * time.Millisecond)
	if err := b.Call(ok); err != nil {
		t.Fatalf("want success after cooldown, got %v", err)
	}
	if err := b.Call(ok); err != nil {
		t.Fatalf("want closed after recovery, got %v", err)
	}
}

