package solution

import (
	"context"
	"errors"
)

var ErrFull = errors.New("bulkhead full")

type Bulkhead struct {
	sem chan struct{} // capacity == max concurrency
}

func NewBulkhead(limit int) *Bulkhead {
	return &Bulkhead{sem: make(chan struct{}, limit)}
}

// Acquire takes a slot without blocking; rejects fast when full.
func (b *Bulkhead) Acquire(ctx context.Context) error {
	select {
	case <-ctx.Done(): // caller already cancelled/timed out
		return ctx.Err()
	default:
	}
	select {
	case b.sem <- struct{}{}: // got a slot
		return nil
	case <-ctx.Done():
		return ctx.Err()
	default:
		return ErrFull // full -> reject rather than pile on
	}
}

// Release frees one slot.
func (b *Bulkhead) Release() { <-b.sem }

// InFlight reports current occupancy (len of the channel).
func (b *Bulkhead) InFlight() int { return len(b.sem) }

