func TestBulkheadCapsAndRejects(t *testing.T) {
	b := NewBulkhead(2)
	ctx := context.Background()

	if err := b.Acquire(ctx); err != nil {
		t.Fatalf("acquire 1: %v", err)
	}
	if err := b.Acquire(ctx); err != nil {
		t.Fatalf("acquire 2: %v", err)
	}
	if got := b.InFlight(); got != 2 {
		t.Fatalf("InFlight = %d, want 2", got)
	}
	// Third acquire must be rejected fast.
	if err := b.Acquire(ctx); !errors.Is(err, ErrFull) {
		t.Fatalf("acquire 3: want ErrFull, got %v", err)
	}
	// Release one and re-acquire.
	b.Release()
	if err := b.Acquire(ctx); err != nil {
		t.Fatalf("re-acquire after release: %v", err)
	}
}

