var client = &http.Client{Timeout: 200 * time.Millisecond} // bound every call
var breaker = &Breaker{Threshold: 5, CooldownFor: 2 * time.Second}

func handle(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), time.Second) // overall budget
	defer cancel()

	var body []byte
	err := func() error {
		for i := 0; i < 3; i++ {
			cerr := breaker.Call(func() error { // fail fast if dep is down
				req, _ := http.NewRequestWithContext(ctx, "GET", "http://downstream/data", nil)
				resp, err := client.Do(req)
				if err != nil {
					return err // transient (timeout/reset)
				}
				defer resp.Body.Close()
				if resp.StatusCode >= 500 {
					return fmt.Errorf("status %d", resp.StatusCode)
				}
				body, err = io.ReadAll(resp.Body)
				return err
			})
			if cerr == nil {
				return nil
			}
			if errors.Is(cerr, ErrOpen) {
				return cerr // don't retry a dead dependency
			}
			backoff := time.Duration(1<<i) * 50 * time.Millisecond
			select {
			case <-time.After(time.Duration(rand.Int63n(int64(backoff)))): // jitter
			case <-ctx.Done():
				return ctx.Err()
			}
		}
		return errors.New("exhausted retries")
	}()
	if err != nil {
		http.Error(w, "upstream unavailable", http.StatusServiceUnavailable)
		return
	}
	w.Write(body)
}

func Retry(
	ctx context.Context,
	attempts int,
	base, cap time.Duration,
	retryable func(error) bool,
	op func(context.Context) error,
) error {
	var err error
	for i := 0; i < attempts; i++ {
		if err = op(ctx); err == nil {
			return nil // success
		}
		// Stop early: last attempt, or a non-retryable (deterministic) error.
		if i == attempts-1 || !retryable(err) {
			return err
		}
		// Exponential backoff, capped.
		backoff := base << i // base * 2^i
		if backoff <= 0 || backoff > cap {
			backoff = cap
		}
		// Full jitter: random wait in [0, backoff).
		wait := time.Duration(rand.Int63n(int64(backoff)))
		select {
		case <-time.After(wait):
		case <-ctx.Done():
			return ctx.Err() // respect the overall deadline
		}
	}
	return err
}
